# %% [markdown]
# ## 4. Exercise 2 — `merge_donors()`: from flagged pairs to one real donor
#
# A flagged pair says that two samples came from the same material, so their two donor ids are one person. Links
# chain: if donor 7 is linked to donor 12 and donor 12 to donor 31, then 7, 12 and 31 are one person, although no
# pair links 7 to 31. `merge_donors(donor, pairs)` takes the manifest donor id of every sample and the flagged pairs
# (sample indices, as exercise 1 returns them) and returns an integer array of the same length: for each sample,
# the **smallest donor id** among all the donors linked to its own, directly or through a chain. A donor that is
# not linked to anything keeps its id, and a pair whose two samples share a donor id changes nothing. The order
# of the pairs must not matter, and the arrays you are given must not be changed. `group_folds` on the result
# then keeps real people whole.
#
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# If the link 7–12 arrives first and 12–31 second, what has to happen to the label of everything already linked to 12?
# What if the two links arrive in the other order? Count how many different donors a chain can have.
# </details>
# <details><summary>💡 Hint 2 — the approach, in words</summary>
#
# Think of donor ids as nodes and flagged pairs as edges, and give every connected group of nodes one name: its
# smallest id. Either keep a table from each id to the smallest id it is known to reach and, when a pair joins two
# groups, point the group with the larger name at the other one; or walk each group once. Whatever you loop on,
# make sure the loop must end, even when the links form a cycle.
# </details>

# %%
def merge_donors(donor: np.ndarray, pairs: list) -> np.ndarray:
    """One real-donor id per sample: link the donors of every flagged pair, and name each chain by its smallest id.

    `donor` is the manifest donor id of every sample (integers); `pairs` is a list of (i, j) sample indices.
    Return an integer array with the shape of `donor`. A chain of links is followed all the way (7-12 and 12-31
    put 7, 12 and 31 in one group). A pair inside one donor changes nothing. Do not change the inputs.

    Example:
        >>> merge_donors(np.array([5, 5, 9, 9, 20]), [(1, 2)]).tolist()      # donors 5 and 9 are one person
        [5, 5, 5, 5, 20]
        >>> merge_donors(np.array([5, 9, 20]), [(0, 1), (1, 2)]).tolist()    # a chain 5-9-20
        [5, 5, 5]

    Returns:
        An integer array, the same length as `donor`.
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_merge_donors() -> None:
    donor = np.array([0, 0, 1, 1, 2, 2, 3, 4])
    pairs = [(1, 2), (3, 4), (7, 6)]
    kept, pairs_kept = donor.copy(), list(pairs)
    got = merge_donors(donor, pairs)
    assert isinstance(got, np.ndarray), f"got a {type(got).__name__}: return a numpy array (one donor id per sample), not a list"
    assert pairs == pairs_kept, "do not change `pairs` (no sorting, reversing or popping of the list you are given)"
    assert got.tolist() == [0, 0, 0, 0, 0, 0, 3, 3], (
        f"expected [0, 0, 0, 0, 0, 0, 3, 3], got {got.tolist()}. Donors 0-1 and 1-2 are linked, so donors 0, 1 and 2 are "
        "ONE person (a chain), named by the smallest id, 0; donors 3 and 4 are linked too. A merge that only follows "
        "direct links leaves donor 2 on its own")
    assert np.array_equal(donor, kept) and np.issubdtype(got.dtype, np.integer), (
        "return a new integer array and do not change `donor`")
    assert merge_donors(donor, pairs[::-1]).tolist() == got.tolist(), "the order of the pairs must not change the result"
    assert merge_donors(donor, []).tolist() == donor.tolist() and merge_donors(donor, [(0, 1)]).tolist() == donor.tolist(), (
        "with no pairs, or a pair inside one donor, every sample keeps its donor id")
    assert merge_donors(np.array([50, 50, 7, 7, 31]), [(1, 2), (3, 4)]).tolist() == [7] * 5, (
        "donor ids need not be 0, 1, 2, ...; the smallest id of the chain (7) names it")
    assert merge_donors(np.array([4, 9, 6]), [(0, 1), (1, 2), (2, 0)]).tolist() == [4, 4, 4], (
        "links that form a cycle must still end, and give the smallest id")
    assert merge_donors(np.array([-5, 10 ** 12, 3, 3]), [(0, 1), (1, 2)]).tolist() == [-5, -5, -5, -5], (
        "donor ids can be any integers (negative, or huge): key a dict by the id, do not use the id as a position in an array")
    print("exercise 2 looks right: chains of linked donors become one person")


# %%
_try("exercise 2", _check_merge_donors)


# %%
def sides_shared(identity: np.ndarray, folds: list) -> int:
    """Over all folds, how many real donors have samples both in the training and in the test samples. Given."""
    return sum(len(np.intersect1d(identity[train], identity[test])) for train, test in folds)


def merged_units(world: int, kind: str) -> np.ndarray:
    """The donor ids of cohort `kind` of world `world` after the donors that share a flagged pair are merged (both layers, R_MIN). Given."""
    return merge_donors(cohort_of(world, kind).donor, flagged_pairs(world, kind))


def _merge_table() -> None:
    kept, rows = [], []
    for w in range(N_WORLDS):
        c = cohort_of(w, "duplicates")
        X = panel_matrix(c, MODALITIES)
        merged = merged_units(w, "duplicates")
        same = len(set(zip(merged.tolist(), c.identity.tolist()))) == len(set(merged.tolist())) == len(set(c.identity.tolist()))
        kept.append(same)
        by_manifest, by_merged = group_folds(c.donor, CV_FOLDS, w), group_folds(merged, CV_FOLDS, w)
        rows.append((sides_shared(c.identity, by_manifest), sides_shared(c.identity, by_merged),
                     protocol_auc("C", w), cv_auc(X, c.y, by_merged), protocol_auc("D", w)))
    a = np.array(rows)
    print(f"merged units are exactly the real donors in {sum(kept)} of {N_WORLDS} worlds")
    print(f"real donors with samples on both sides of a fold, summed over the {CV_FOLDS} folds, mean over worlds: "
          f"folds by manifest donor {a[:, 0].mean():.1f}, folds by merged unit {a[:, 1].mean():.1f}")
    print(f"cross-validated AUC, mean over worlds (standard error): by manifest donor {a[:, 2].mean():.3f} ({_se(a[:, 2]):.3f}), "
          f"by merged unit {a[:, 3].mean():.3f} ({_se(a[:, 3]):.3f}), by real donor (answer key) {a[:, 4].mean():.3f} ({_se(a[:, 4]):.3f})")
    back = a[:, 2] - a[:, 3]
    print(f"what merging took back: {_signed(back.mean())} AUC (standard error {_se(back):.3f}); "
          f"merged minus real-donor folds: {_signed((a[:, 3] - a[:, 4]).mean())}")


if _DEMOS:
    _try("merging the flagged donors", _merge_table, needs=("exercise 1", "exercise 2"))

# %% [markdown]
# ## 5. Exercise 3 — `batch_case_share()`: how many cases are on each plate?
#
# If the plate predicts the outcome, a biomarker model can read the plate: Leek and colleagues call batch effects
# that are correlated with an outcome of interest a major problem (`claims.yaml`). The first thing to look at is the
# share of cases on each plate. Count **donors**, not samples. The outcome belongs to a donor; a donor with four samples
# is still one donor; and here cases give more samples than controls, so a count of samples is pulled towards the
# cases and no longer says how many donors of each kind a plate holds (the cell below prints both).
#
# Every distinct pair (batch, donor) counts once, in that batch, with the label of its first sample; a donor with
# samples on two plates counts once on each. Return `(batches, shares)`: the batch ids in increasing order, and for
# each the share of the donors in it that are cases, as floats between 0 and 1. A range of shares says how
# unbalanced the plates are, not whether that is more than chance would do; exercise 4 supplies the chance.
#
# <details><summary>💡 Hint 1 — what to think about</summary>
#
# How many rows should a donor with four samples on one plate contribute? What do you have to remove before you
# take a mean? Which `np.unique` option gives you one position per distinct combination?
# </details>
# <details><summary>💡 Hint 2 — the approach, in words</summary>
#
# Find the first sample of every distinct (batch, donor) combination, keep only those samples' batch and label,
# then for each batch id in increasing order take the mean of the labels. A batch with no case has share 0.0.
# </details>

# %%
def batch_case_share(batch: np.ndarray, donor: np.ndarray, y: np.ndarray) -> tuple:
    """Share of case DONORS in every batch: each distinct (batch, donor) pair counts once.

    `batch`, `donor` (integer ids) and `y` (1 for a case, 0 for a control) have one entry per sample; all of a
    donor's samples carry the donor's label. Return `(batches, shares)`: the sorted batch ids, and the fraction
    of the donors in each batch that are cases.

    Example:
        >>> batch = np.array([1, 1, 1, 1, 2, 2, 2])
        >>> donor = np.array([10, 10, 10, 11, 12, 13, 14])
        >>> y = np.array([1, 1, 1, 0, 0, 1, 0])
        >>> batches, shares = batch_case_share(batch, donor, y)    # batch 1 has 3 case SAMPLES out of 4, but 1 case donor of 2
        >>> batches.tolist(), shares.round(3).tolist()
        ([1, 2], [0.5, 0.333])

    Returns:
        A tuple of two arrays: the batch ids and the case share of each.
    """
    # YOUR CODE HERE
    raise NotImplementedError


def _check_batch_case_share() -> None:
    batch = np.array([1, 1, 1, 1, 2, 2, 2])
    donor = np.array([10, 10, 10, 11, 12, 13, 14])
    y = np.array([1, 1, 1, 0, 0, 1, 0])
    plates, shares = batch_case_share(batch, donor, y)
    assert isinstance(plates, np.ndarray) and isinstance(shares, np.ndarray), (
        "return two numpy arrays (the batch ids and the case shares), not lists")
    assert plates.tolist() == [1, 2] and np.allclose(shares, [0.5, 1 / 3], rtol=0, atol=1e-12), (
        f"expected batches [1, 2] and shares [0.5, 0.3333], got {plates.tolist()} and {np.round(shares, 4).tolist()}. "
        "Count DONORS: donor 10 has three samples on plate 1 but is one case donor, so plate 1 has one case donor "
        "of two (0.5), not three case samples of four (0.75)")
    plates, shares = batch_case_share(np.array([7, 7, 3, 3, 3, 9]), np.array([1, 1, 2, 3, 3, 4]), np.array([0, 0, 1, 0, 0, 1]))
    assert plates.tolist() == [3, 7, 9] and shares.tolist() == [0.5, 0.0, 1.0], (
        f"expected batches [3, 7, 9] with shares [0.5, 0.0, 1.0], got {plates.tolist()} and {shares.tolist()}. "
        "Batch ids need not be 0, 1, 2, ...: return them in increasing order; a plate with no case has share 0.0, "
        "a plate with only cases 1.0")
    plates, shares = batch_case_share(np.array([1, 2]), np.array([5, 5]), np.array([1, 1]))
    assert plates.tolist() == [1, 2] and shares.tolist() == [1.0, 1.0], (
        "a donor with samples on two plates counts once on EACH plate")
    print("exercise 3 looks right: the case share of every plate, counted by donor")


