def _share_table() -> None:
    print("share of case DONORS on each plate (in brackets: the share of case SAMPLES), world 0")
    for kind in COHORT_KINDS:
        c = cohort_of(0, kind)
        for name in MODALITIES:
            batch = getattr(c, "batch_" + name)
            plates, shares = batch_case_share(batch, c.donor, c.y)
            by_sample = [float(c.y[batch == b].mean()) for b in plates]
            cells = "  ".join(f"{s:.2f} ({t:.2f})" for s, t in zip(shares, by_sample))
            print(f"  {kind:<11} {name:<10} {cells}   range {shares.max() - shares.min():.2f}")
    print(f"range of the donor-level case share over the {N_WORLDS} worlds (smallest to largest):")
    for kind in ("balanced", "duplicates", "confounded"):
        for name in MODALITIES:
            spans = []
            for w in range(N_WORLDS):
                c = cohort_of(w, kind)
                shares = batch_case_share(getattr(c, "batch_" + name), c.donor, c.y)[1]
                spans.append(float(shares.max() - shares.min()))
            print(f"  {kind:<11} {name:<10} {min(spans):.2f} to {max(spans):.2f}")


